--   drop function if exists public.talkx_campaign_window_open(uuid, timestamptz);
--   delete from public.talkx_settings where key = 'dnd_hours' and value = '{"start":"22:00","end":"08:00","sundays":true,"holidays":[]}'::jsonb and description = 'Janela "não perturbe": envios só fora deste horário quando respect_dnd=true';
--   alter table public.talkx_campaigns drop column if exists send_weekdays;
--   alter table public.talkx_campaigns drop column if exists respect_dnd;
--
-- N-102 · fatia 'rollback' (t_7fa3929d). Esta migration existe por dois defeitos que
-- estavam no bloco de rollback da série N-102.
--
-- (1) DELIMITADORES TROCADOS. O bloco de rollback da base
-- 20261009203548_talkx_campaigns_send_weekdays_dnd.sql restaura as duas RPCs com 'as $$'
-- na abertura e '$function$;' no fechamento: o corpo abre com uma tag e fecha com outra,
-- então o SQL extraído do bloco não executa (erro de sintaxe). Esta fatia não pode editar
-- a base (cartão), então o bloco CORRIGIDO — com $function$ nas DUAS pontas de cada
-- função — vive nas linhas '--   ' acima e É o rollback executável da série. Nenhuma
-- linha desta migration abre ou fecha corpo de função com delimitador trocado.
--
-- (2) ESCRITA QUE SOBRESCREVIA O DONO ALHEIO. A base grava o default de dnd_hours com
-- 'ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, description = EXCLUDED.description',
-- que sobrescreve value/description de QUALQUER linha já existente com a mesma key —
-- inclusive a de outro dono. Subir a série destruía o valor alheio e o rollback (que apaga
-- só o default desta série) já não tinha o que restaurar: a operação era irreversível.
-- O corpo abaixo usa o MESMO upsert com a guarda
-- 'WHERE public.talkx_settings.value = EXCLUDED.value': só reafirma a linha cujo value já
-- é o default desta série; linha de outro dono (value diferente) não é tocada. O rollback
-- apaga a linha somente se ela continuar sendo o default desta série, então o valor de
-- outro dono sobrevive ao up E ao down.
--
-- Efeitos colaterais: um único INSERT ... ON CONFLICT sobre uma linha; nenhuma coluna,
-- função, ACL, GRANT, policy ou papel é alterado; nenhum DEFAULT muda; a linha de outro
-- dono não dispara gatilho de updated_at (o UPDATE não chega a rodar nela). Sem BEGIN/COMMIT
-- — o ledger aplica cada migration em transação própria.

INSERT INTO public.talkx_settings (key, value, description)
VALUES ('dnd_hours',
        '{"start":"22:00","end":"08:00","sundays":true,"holidays":[]}'::jsonb,
        'Janela "não perturbe": envios só fora deste horário quando respect_dnd=true')
ON CONFLICT (key) DO UPDATE
  SET value = EXCLUDED.value,
      description = EXCLUDED.description
  WHERE public.talkx_settings.value = EXCLUDED.value;
